from __future__ import annotations

import json

import pytest

import chief_llm


def _openrouter_metadata() -> dict[str, str]:
    return {"data_classification": "synthetic_public", "cloud_allowed": "true"}


class _OpenRouterResp:
    def __init__(self, payload: dict | str, *, status: int = 200):
        self.status = status
        self._payload = payload

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        return False

    def read(self):
        if isinstance(self._payload, str):
            return self._payload.encode("utf-8")
        return json.dumps(self._payload).encode("utf-8")


def _forbidden_request(*args, **kwargs):
    raise AssertionError("OpenRouter request must not be constructed")


def test_choose_local_model_lane_prefers_fast_for_small_classifier_prompt():
    prompt = "Classify this message by intent and return JSON only."

    assert chief_llm.choose_local_model_lane(prompt) == "fast"


def test_choose_local_model_lane_prefers_strong_by_default():
    prompt = "Write a practical response to this short note."

    assert chief_llm.choose_local_model_lane(prompt) == "strong"


def test_choose_local_model_lane_prefers_deep_for_long_synthesis_prompt():
    prompt = ("Please synthesize this material into a reflection report. " * 90).strip()

    assert chief_llm.choose_local_model_lane(prompt) == "deep"


def test_local_model_route_reason_is_explicit_and_lane_correct():
    assert "fast-lane policy" in chief_llm.local_model_route_reason(
        "Classify this message by intent and return JSON only.",
        "fast",
    )
    assert "default strong lane" in chief_llm.local_model_route_reason(
        "Write a practical response to this short note.",
        "strong",
    )
    assert "deep threshold" in chief_llm.local_model_route_reason(
        ("Please synthesize this material into a reflection report. " * 90).strip(),
        "deep",
    )


def test_resolve_local_model_uses_installed_lane_candidate(monkeypatch):
    monkeypatch.setattr(
        chief_llm,
        "_ollama_installed_models",
        lambda force_refresh=False: {"gemma4:26b", "gemma4:31b", "qwen2.5-coder:14b"},
    )

    model, lane = chief_llm.resolve_local_model("Write a practical reply.")

    assert lane == "strong"
    assert model == "gemma4:31b"

import json
from pathlib import Path

from scripts.export_read_models import (
    CLAIMS_NOT_MADE,
    EXPORT_VERSION,
    EXPECTED_EXPORT_PATHS,
    build_expected_exports,
    export_read_models,
    format_operator_export_summary,
    main,
)


def _export_root(tmp_path):
    return tmp_path / "generated" / "read_models"


def _summary(tmp_path):
    return export_read_models(export_root=_export_root(tmp_path))


def test_export_directory_is_created(tmp_path):
    export_root = _export_root(tmp_path)

    assert not export_root.exists()
    summary = export_read_models(export_root=export_root)

    assert export_root.is_dir()
    assert summary["export_root"] == export_root.as_posix()


def test_expected_exports_exist(tmp_path):
    summary = _summary(tmp_path)
    paths = {export["path"] for export in summary["exports"]}

    assert paths == {
        (_export_root(tmp_path) / path).as_posix()
        for path in EXPECTED_EXPORT_PATHS
    }
    for path in paths:
        assert Path(path).is_file()
    assert (_export_root(tmp_path) / "world_status.json").is_file()
    assert (_export_root(tmp_path) / "world_status.operator.txt").is_file()
    assert (_export_root(tmp_path) / "evidence_freshness.json").is_file()
    assert (_export_root(tmp_path) / "evidence_freshness.operator.txt").is_file()


def test_expected_json_exports_parse(tmp_path):
    summary = _summary(tmp_path)

    for export in summary["exports"]:
        if export["format"] != "json":
            continue
        with Path(export["path"]).open("r", encoding="utf-8") as handle:
            payload = json.load(handle)
        assert isinstance(payload, dict)


def test_expected_operator_text_exports_exist(tmp_path):
    summary = _summary(tmp_path)
    operator_paths = [
        Path(export["path"])
        for export in summary["exports"]
        if export["format"] == "operator_text"
    ]

    assert operator_paths
    for path in operator_paths:
        text = path.read_text(encoding="utf-8")
        assert "Evidence:" in text
        assert "Boundary:" in text
        assert "Blocked:" in text
        assert "Next safe move:" in text


def test_exports_are_metadata_read_model_only(tmp_path):
    summary = _summary(tmp_path)

    assert summary["export_version"] == EXPORT_VERSION
